  static Surah byNumber(int number) {
    if (number < 1 || number > all.length) return all.first;
    return all[number - 1];
  }

  static List<Surah> search(String query) {
    final normalized = query.trim().toLowerCase();
    if (normalized.isEmpty) return all;
    return all.where((surah) {
      return surah.name.toLowerCase().contains(normalized) ||
          surah.translation.toLowerCase().contains(normalized) ||
          surah.arabicName.contains(query.trim()) ||
          surah.number.toString() == normalized;
    }).toList(growable: false);
  }

